(function(global){
'use strict';
const sec=global.PoolShedSettingsPermissions;if(!sec)return;
const PAGES=['Overview','Production Readiness','Users','Roles & Permissions','Approval Limits','Locations & Access','Financial Visibility','Automation & Assistant','Integrations','Notifications','Company Settings','Audit & Security'];
const MODULE_LABELS={dashboard:'Dashboard',crm:'CRM',jobs:'Projects',salesorders:'Sales Orders',quotes:'Quotes',products:'Product Hub',locations:'Inventory',purchase:'Purchasing',warehouse:'Warehouse',fulfilment:'Fulfilment',accounting:'Accounting',analytics:'Analytics',automation:'Automation',settings:'Settings'};
const OP_LABELS={view:'View',create:'Create',edit:'Edit',delete:'Delete',export:'Export',approve:'Approve',override:'Override',configure:'Configure'};
let selectedRole='Management';let inspectorUserId='',inspectorModule='dashboard',inspectorOperation='view';
function d(){return global.__POOL_SHED_GET_DATA__?global.__POOL_SHED_GET_DATA__():(global.data||{});}function users(){return sec.users();}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function save(){try{if(typeof global.saveAppData==='function')global.saveAppData();}catch(_){}}function toastMsg(m){try{if(typeof toast==='function')toast(m);else console.log(m);}catch(_){console.log(m);}}
function pill(text,kind){return '<span class="settings-pill '+(kind||'')+'">'+esc(text)+'</span>';}function button(text,action,kind,attrs){return '<button type="button" class="settings-btn '+(kind||'')+'" data-settings-action="'+action+'" '+(attrs||'')+'>'+esc(text)+'</button>';}
function page(){try{return selectedSubPage('settings')||'Overview';}catch(_){return 'Overview';}}
function layout(title,subtitle,body,actions){return '<section class="settings-command"><header class="settings-command-head"><div><span class="settings-eyebrow">SETTINGS CONTROL</span><h1>'+esc(title)+'</h1><p>'+esc(subtitle)+'</p></div><div class="settings-head-actions">'+(actions||'')+'</div></header><nav class="settings-command-tabs">'+PAGES.map(p=>'<button type="button" class="'+(page()===p?'on':'')+'" data-settings-page="'+esc(p)+'">'+esc(p)+'</button>').join('')+'</nav><div class="settings-command-body">'+body+'</div></section>';}
function metric(label,value,note,target,kind){return '<button type="button" class="settings-metric '+(kind||'')+'" data-settings-page="'+esc(target)+'"><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong><small>'+esc(note)+'</small></button>';}
function overview(){const s=sec.securitySummary(),us=users(),invited=us.filter(u=>/invited/i.test(String(u.status||''))).length,integrations=(d().integrations||[]),healthy=integrations.filter(i=>/connected|healthy|ready to connect/i.test(String(i.status||''))).length,aud=(d().auditLog||[]).filter(a=>a.category==='Security'||/permission|approval|access|security|export/i.test(String(a.action||''))).slice(0,6);return layout('Settings, Users & Permissions','Control who can see, change, approve, export and automate across Pool Shed.',
'<div class="settings-metrics">'+metric('Active Users',s.activeUsers,invited+' invite pending','Users','good')+metric('Roles',s.roles,'Role + individual overrides','Roles & Permissions')+metric('Approval Gaps',s.approvalGaps,'Need review','Approval Limits',s.approvalGaps?'warn':'good')+metric('Integrations',healthy+' / '+integrations.length,'Connection health','Integrations',healthy===integrations.length?'good':'warn')+metric('Admin Users',s.adminUsers,'Full authority','Audit & Security')+metric('Security Attention',s.inactiveAdmins+(s.approvalGaps||0),'Actionable controls','Audit & Security',(s.inactiveAdmins+s.approvalGaps)?'warn':'good')+'</div>'+
'<div class="settings-grid two"><section class="settings-panel"><header><h2>Security Health</h2>'+pill((s.approvalGaps||s.inactiveAdmins)?'Needs review':'Healthy',(s.approvalGaps||s.inactiveAdmins)?'warn':'good')+'</header><div class="settings-panel-body">'+health(s.approvalGaps?'warn':'good',s.approvalGaps?s.approvalGaps+' users/roles need approval authority review':'Approval authority is configured','Creation and approval remain separate permissions.','Approval Limits')+health('good','Full System Export is restricted',s.fullExportUsers+' active user'+(s.fullExportUsers===1?'':'s')+' currently have full export authority.','Roles & Permissions')+health('good','Assistant permissions inherit user access','The assistant cannot retrieve Finance, margins, supplier costs or customer credit data the signed-in user cannot open.','Automation & Assistant')+health(global.PoolShedProductionReadiness&&global.PoolShedProductionReadiness.inspect().blockers.length?'warn':'good','Production readiness','End-to-end journey and go-live diagnostics are available in Settings.','Production Readiness')+health(s.inactiveAdmins?'warn':'good',s.inactiveAdmins?s.inactiveAdmins+' inactive Admin account needs review':'No inactive Admin access detected','Disabled/inactive privileged access should be reviewed immediately.','Users')+'</div></section>'+
'<section class="settings-panel"><header><h2>Quick Administration</h2></header><div class="settings-panel-body">'+quick('U','Add a staff user','Assign a base role, locations and approval authority.',button('+ Add User','add-user','primary'))+quick('R','Review a role','Check inherited permissions and deliberate overrides.',button('Role Builder','goto-page','', 'data-page-target="Roles & Permissions"'))+quick('👁','View system as a user','Preview their effective navigation and sensitive-data visibility.',button('Preview','preview-user',''))+'</div></section></div>'+
'<section class="settings-panel"><header><h2>Recent Sensitive Activity</h2>'+button('Open Audit','goto-page','','data-page-target="Audit & Security"')+'</header><div class="settings-panel-body">'+(aud.length?aud.map(a=>'<div class="settings-audit-row"><div><strong>'+esc(a.action||'Security change')+'</strong><small>'+esc(a.target||a.product||'Pool Shed')+'</small></div><span>'+esc(a.user||'User')+'</span><span>'+esc((a.date||'').replace('T',' ').slice(0,16))+'</span>'+pill(a.category||'Security','warn')+'</div>').join(''):'<div class="settings-empty">No sensitive changes recorded yet.</div>')+'</div></section>',button('View as User','preview-user')+button('+ Add User','add-user','primary'));}
function health(kind,title,text,target){return '<article class="settings-health '+kind+'"><span class="settings-health-icon">'+(kind==='good'?'✓':'!')+'</span><div><strong>'+esc(title)+'</strong><p>'+esc(text)+'</p></div><button type="button" data-settings-page="'+esc(target)+'">Review</button></article>';}
function quick(icon,title,text,action){return '<article class="settings-quick"><span>'+icon+'</span><div><strong>'+esc(title)+'</strong><small>'+esc(text)+'</small></div>'+action+'</article>';}

function readinessPage(){const engine=global.PoolShedProductionReadiness;if(!engine)return layout('Production Readiness','End-to-end operational and release diagnostics.','<div class="settings-callout warn"><strong>Readiness engine unavailable</strong><p>Reload Pool Shed so the production-readiness authority can initialise.</p></div>');const r=engine.inspect(),stateKind=r.status==='Blocked'?'danger':r.status==='Ready with attention'?'warn':'good';const journeyRows=r.journeys.map(j=>'<tr><td><strong>'+esc(j.label)+'</strong><small>'+esc(j.id)+'</small></td><td>'+pill(j.state==='ready'?'Ready':j.state==='blocked'?'Blocked':'Needs attention',j.state==='ready'?'good':j.state==='blocked'?'danger':'warn')+'</td><td>'+j.blockers+'</td><td>'+j.attention+'</td><td>'+(j.issues.length?button('Review '+j.issues.length,'open-readiness-issue','mini','data-readiness-code="'+esc(j.issues[0].code)+'"'):'<span class="muted">No exceptions</span>')+'</td></tr>').join('');const issueRows=r.issues.map(x=>{const rt=engine.routeForIssue(x);return '<tr><td>'+pill(x.severity==='blocker'?'Blocker':'Attention',x.severity==='blocker'?'danger':'warn')+'</td><td><strong>'+esc(x.title)+'</strong><small>'+esc(x.detail)+'</small></td><td>'+esc((r.journeys.find(j=>j.id===x.journey)||{}).label||x.journey)+'</td><td>'+button('Open '+(rt.page||'record'),'open-readiness-issue','mini','data-readiness-code="'+esc(x.code)+'"')+'</td></tr>';}).join('');const systemRows=r.systemChecks.map(x=>'<div class="readiness-check"><span class="readiness-dot '+(x.state==='pass'?'good':'bad')+'">'+(x.state==='pass'?'✓':'!')+'</span><div><strong>'+esc(x.label)+'</strong><small>'+esc(x.detail)+'</small></div>'+pill(x.state==='pass'?'Loaded':'Blocked',x.state==='pass'?'good':'danger')+'</div>').join('');const integrations=(d().integrations||[]),integrationRows=integrations.length?integrations.map(x=>'<div class="readiness-check"><span class="readiness-dot '+(/connected|healthy|ready to connect/i.test(String(x.status||''))?'good':'warn')+'">'+(/connected|healthy|ready to connect/i.test(String(x.status||''))?'✓':'!')+'</span><div><strong>'+esc(x.name||x.id||'Integration')+'</strong><small>'+esc(x.status||'Not configured')+'</small></div>'+button('Review','goto-page','mini','data-page-target="Integrations"')+'</div>').join(''):'<div class="settings-empty">No integration records are configured in this workspace.</div>';const checklist=[['System authorities loaded',r.systemChecks.every(x=>x.state==='pass')],['No physical-stock blockers',!r.blockers.some(x=>/stock/i.test(x.code+' '+x.title))],['Permission and approval authority healthy',!r.blockers.some(x=>/approval|admin|permission/i.test(x.code+' '+x.title))],['Assistant restricted to Pool Shed data',r.answerPolicy==='Pool Shed only'],['Critical journeys covered',r.journeys.length===7],['Production build/browser acceptance',false]];return layout('Production Readiness','One place to verify critical journeys, operational exceptions and go-live controls before production.',
'<div class="readiness-hero"><div><span class="settings-eyebrow">RELEASE HEALTH · v'+esc(r.version)+'</span><h2>'+esc(r.status)+'</h2><p>'+r.summary.journeysReady+' of '+r.summary.journeysTotal+' critical journeys currently have no live exceptions.</p></div><div class="readiness-score '+stateKind+'"><strong>'+r.score+'</strong><span>/ 100</span><small>'+r.blockers.length+' blockers · '+r.attention.length+' attention</small></div></div>'+ 
'<div class="settings-grid two"><section class="settings-panel"><header><div><h2>Release Health</h2><p>Required Pool Shed authority engines and safety controls.</p></div>'+pill(r.systemChecks.every(x=>x.state==='pass')?'Authorities loaded':'Blocked',r.systemChecks.every(x=>x.state==='pass')?'good':'danger')+'</header><div class="settings-panel-body">'+systemRows+'</div></section><section class="settings-panel"><header><div><h2>Environment & Integrations</h2><p>Runtime connections and acceptance constraints.</p></div>'+button('Review Integrations','goto-page','','data-page-target="Integrations"')+'</header><div class="settings-panel-body">'+integrationRows+'<div class="readiness-env"><span>Database automation</span><strong>'+esc(r.environment.databaseAutomation)+'</strong></div><div class="readiness-env"><span>Browser automation</span><strong>'+esc(r.environment.browserAutomation)+'</strong></div></div></section></div>'+ 
'<section class="settings-panel"><header><div><h2>Critical Journeys</h2><p>End-to-end coverage across the business, from customer order through finance and reporting.</p></div></header><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>Journey</th><th>Status</th><th>Blockers</th><th>Attention</th><th>Action</th></tr></thead><tbody>'+journeyRows+'</tbody></table></div></section>'+ 
'<section class="settings-panel"><header><div><h2>Operational Attention</h2><p>Live work that needs action. These records do not automatically mean the software is unsafe to run.</p></div>'+button('Run Check','run-readiness-check')+'</header><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>Severity</th><th>Finding</th><th>Journey</th><th>Action</th></tr></thead><tbody>'+(issueRows||'<tr><td colspan="4" class="settings-empty">No live readiness exceptions found.</td></tr>')+'</tbody></table></div></section>'+ 
'<section class="settings-panel"><header><div><h2>Go-Live Checklist</h2><p>Final controls before treating a build as production accepted.</p></div>'+button('Export Readiness Report','export-readiness-report','primary')+'</header><div class="settings-panel-body readiness-checklist">'+checklist.map(([label,ok])=>'<div><span class="readiness-dot '+(ok?'good':'warn')+'">'+(ok?'✓':'!')+'</span><strong>'+esc(label)+'</strong><small>'+(ok?'Verified in this workspace':'Requires release/environment acceptance evidence')+'</small></div>').join('')+'</div></section>');}

function usersPage(){const rows=users().map(u=>{const e=sec.effective(u),loc=e.locations.length?e.locations.join(', '):'All authorised locations',fin=Object.values(e.financialVisibility).some(Boolean)?'Controlled visibility':'Hidden',limits=e.approvalLimits,po=limits.purchaseOrder===null?'Unlimited':(limits.purchaseOrder?('£'+Number(limits.purchaseOrder).toLocaleString('en-GB')):'No PO approval');return '<tr><td><div class="settings-user"><span>'+esc((u.name||'?').split(/\s+/).map(x=>x[0]).slice(0,2).join(''))+'</span><div><strong>'+esc(u.name||'User')+'</strong><small>'+esc(u.email||u.id)+'</small></div></div></td><td>'+pill(e.role,e.role==='Admin'?'danger':'')+'</td><td>'+esc(loc)+'</td><td>'+esc(fin)+'</td><td>'+esc(po)+'</td><td>'+esc(u.lastActivity||'Not recorded')+'</td><td>'+pill(u.status||'Active',/disabled|suspend/i.test(String(u.status))?'warn':'good')+'</td><td>'+button('Open','edit-user','mini','data-user-id="'+esc(u.id)+'"')+'</td></tr>';}).join('');return layout('Users','Manage identity, base role, status, access scope and individual exceptions.','<div class="settings-toolbar"><input id="settingsUserSearch" placeholder="Search user, role or email"><span class="grow"></span>'+button('View as User','preview-user')+button('+ Add User','add-user','primary')+'</div><section class="settings-panel"><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>User</th><th>Role</th><th>Locations / Scope</th><th>Financial Visibility</th><th>Approval Authority</th><th>Last Activity</th><th>Status</th><th></th></tr></thead><tbody id="settingsUserRows">'+rows+'</tbody></table></div></section>');}
function permissionInspector(){const list=users();if(!list.length)return '<section class="settings-panel permission-inspector"><div class="settings-empty">No staff profiles are available to inspect.</div></section>';let u=list.find(x=>String(x.id)===String(inspectorUserId))||list[0];inspectorUserId=String(u.id);const effective=sec.effective(u),explanation=sec.explain(inspectorModule,inspectorOperation,u),visible=sec.modules().filter(m=>sec.can(m,'view',u)),blocked=sec.modules().filter(m=>!sec.can(m,'view',u)),scope=effective.locations||[],limits=effective.approvalLimits||{},finance=effective.financialVisibility||{};const sourceLabels={'admin':'Admin authority','user-override':'Individual override','location-scope':'Location scope','approval-limit':'Approval threshold','role':'Inherited role','system':'System rule'};return '<section class="settings-panel permission-inspector"><header><div><h2>Permission Inspector</h2><p>Read-only explanation of the exact authority Pool Shed will enforce for a member of staff.</p></div>'+pill(explanation.allowed?'Allowed':'Blocked',explanation.allowed?'good':'danger')+'</header><div class="settings-panel-body"><div class="permission-inspector-controls"><label>Staff member<select data-permission-inspector-user>'+list.map(x=>'<option value="'+esc(x.id)+'"'+(String(x.id)===String(u.id)?' selected':'')+'>'+esc(x.name||x.email||x.id)+' · '+esc(x.role||'Office')+'</option>').join('')+'</select></label><label>Area<select data-permission-inspector-module>'+sec.modules().map(m=>'<option value="'+m+'"'+(m===inspectorModule?' selected':'')+'>'+esc(MODULE_LABELS[m]||m)+'</option>').join('')+'</select></label><label>Operation<select data-permission-inspector-operation>'+sec.operations().filter(op=>op!=='fullSystemExport').map(op=>'<option value="'+op+'"'+(op===inspectorOperation?' selected':'')+'>'+esc(OP_LABELS[op]||op)+'</option>').join('')+'</select></label></div><div class="permission-inspector-identity"><div><span>Canonical role</span><strong>'+esc(effective.role)+'</strong></div><div><span>Account status</span><strong>'+esc(u.status||'Active')+'</strong></div><div><span>Visible modules</span><strong>'+visible.length+' / '+sec.modules().length+'</strong></div><div><span>Scoped locations</span><strong>'+(scope.length?scope.length:'All')+'</strong></div></div><div class="permission-inspector-explanation '+(explanation.allowed?'allowed':'blocked')+'"><span>'+esc(sourceLabels[explanation.source]||explanation.source)+'</span><strong>'+esc(explanation.allowed?'Access allowed':'Access blocked')+'</strong><p>'+esc(explanation.reason)+'</p></div><div class="permission-inspector-grid"><div><h3>Module access</h3><div class="preview-tags">'+visible.map(m=>pill(MODULE_LABELS[m]||m,'good')).join('')+blocked.map(m=>pill(MODULE_LABELS[m]||m,'muted')).join('')+'</div></div><div><h3>Financial visibility</h3><div class="preview-tags">'+Object.keys(finance).map(k=>pill(k,finance[k]?'good':'muted')).join('')+'</div></div><div><h3>Approval authority</h3><div class="permission-limit-list">'+Object.keys(limits).map(k=>'<span><small>'+esc(k)+'</small><strong>'+(limits[k]===null?'Unlimited':'£'+Number(limits[k]||0).toLocaleString('en-GB'))+'</strong></span>').join('')+'</div></div><div><h3>Location scope</h3><p>'+(scope.length?esc(scope.join(', ')):'All authorised locations')+'</p></div></div></div></section>';}
function rolesPage(){const roles=sec.roles(),matrix=sec.roleMatrix(selectedRole),ops=['view','create','edit','delete','export','approve','override','configure'];return layout('Roles & Permissions','Use a clear base role, then individual overrides only for deliberate exceptions.','<div class="settings-role-picker">'+roles.map(r=>'<button type="button" class="'+(r.id===selectedRole?'on':'')+'" data-settings-role="'+r.id+'">'+esc(r.label)+'</button>').join('')+'</div>'+permissionInspector()+'<section class="settings-panel"><header><div><h2>'+esc(selectedRole)+' Role Builder</h2><p>Changes apply to the base role. Individual user overrides are shown separately on the user record.</p></div>'+button('Save Role','save-role','primary')+'</header><div class="settings-panel-body settings-table-wrap"><table class="settings-table permission-matrix"><thead><tr><th>Area</th>'+ops.map(op=>'<th>'+OP_LABELS[op]+'</th>').join('')+'</tr></thead><tbody>'+sec.modules().map(m=>'<tr><td><strong>'+esc(MODULE_LABELS[m]||m)+'</strong></td>'+ops.map(op=>'<td><button type="button" class="permission-toggle '+(matrix[m]&&matrix[m][op]?'on':'')+'" data-settings-action="toggle-role-permission" data-module="'+m+'" data-operation="'+op+'">'+(matrix[m]&&matrix[m][op]?'✓':'–')+'</button></td>').join('')+'</tr>').join('')+'</tbody></table></div></section><div class="settings-callout info"><strong>Deny wins for individual overrides</strong><p>If a user has an explicit deny on a permission, the assistant, exports and automations receive the same deny even when the base role would normally allow it.</p></div>');}
const APPROVAL_KEYS=[['purchaseOrder','Purchase Order approval'],['supplierPayment','Supplier payment'],['creditLimitChange','Customer credit-limit change'],['stockWriteOff','Stock write-off'],['priceOverride','Price override'],['marginException','Margin exception'],['automationActivation','Automation activation']];
function approvalsPage(){const roles=sec.roles().map(r=>r.id);return layout('Approval Limits','Creation and approval are separate permissions. Limits route higher-value actions to the next authority.','<div class="settings-callout info"><strong>Example</strong><p>A Purchasing user can create an £8,420 PO, but with a £5,000 approval limit it routes to Management before it can be approved.</p></div>'+roles.map(role=>{const limits=sec.approvalLimits(role);return '<section class="settings-panel approval-card"><header><h2>'+esc(role)+'</h2>'+pill(role==='Admin'?'Unlimited authority':'Controlled','')+'</header><div class="settings-panel-body settings-approval-grid">'+APPROVAL_KEYS.map(([key,label])=>'<label><span>'+esc(label)+'</span><input data-approval-role="'+role+'" data-approval-key="'+key+'" value="'+(limits[key]===null?'Unlimited':Number(limits[key]||0))+'" '+(role==='Admin'?'disabled':'')+'></label>').join('')+'</div></section>';}).join(''),button('Test Approval Route','test-approval')+button('Save Limits','save-approval','primary'));}
function locationsPage(){const locs=d().locations||[];return layout('Locations & Access','Restrict staff to the branches, warehouses, vans and project stock they are authorised to operate.','<section class="settings-panel"><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>User</th>'+locs.slice(0,8).map(l=>'<th>'+esc(l.name)+'</th>').join('')+'<th>Scope</th></tr></thead><tbody>'+users().map(u=>'<tr><td><strong>'+esc(u.name)+'</strong><small>'+esc(u.role)+'</small></td>'+locs.slice(0,8).map(l=>'<td><button type="button" class="permission-toggle '+(sec.canLocation(l.id,u)?'on':'')+'" data-settings-action="toggle-location" data-user-id="'+esc(u.id)+'" data-location-id="'+esc(l.id)+'">'+(sec.canLocation(l.id,u)?'✓':'–')+'</button></td>').join('')+'<td>'+esc(sec.effective(u).locations.length?'Restricted':'All authorised')+'</td></tr>').join('')+'</tbody></table></div></section><div class="settings-callout info"><strong>Location scope also applies to Find Anything</strong><p>The assistant cannot reveal stock from a location that is outside the signed-in user’s authorised scope.</p></div>',button('Save Location Access','save-location-scope','primary'));}
const FIN=[['customerBalances','Customer balances'],['customerCreditLimits','Customer credit limits'],['supplierCosts','Supplier costs'],['productMargins','Product margin'],['supplierBills','Supplier balances / bills'],['paymentRuns','Payment runs'],['projectMargins','Project commercial margin'],['financialExports','Full system financial export']];
function financePage(){const roles=sec.roles().map(r=>r.id),rows=FIN.map(([key,label])=>'<tr><td><strong>'+esc(label)+'</strong></td>'+roles.map(role=>'<td><button type="button" class="permission-toggle '+(sec.financeMatrix(role)[key]?'on':'')+'" data-settings-action="toggle-finance" data-role="'+role+'" data-finance-key="'+key+'">'+(sec.financeMatrix(role)[key]?'✓':'–')+'</button></td>').join('')+'</tr>').join('');return layout('Financial Visibility','Control sensitive balances, costs, margins, payment data and financial exports separately from module access.','<section class="settings-panel"><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>Financial Data</th>'+roles.map(r=>'<th>'+esc(r)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div></section><div class="settings-callout info"><strong>Assistant and Analytics use this same visibility</strong><p>If a user cannot see supplier cost or project margin directly, Analytics exports and the assistant cannot expose it either.</p></div>',button('Save Visibility','save-financial-visibility','primary'));}
function assistantPage(){if(global.PoolShedAutomationWorkspace&&typeof global.PoolShedAutomationWorkspace.renderSettingsPanel==='function')return layout('Automation & Assistant','Assistant identity, Pool Shed-only knowledge, training and automation authority are controlled here.',global.PoolShedAutomationWorkspace.renderSettingsPanel()+'<div class="settings-grid two"><section class="settings-panel"><header><h2>Assistant Permission Contract</h2></header><div class="settings-panel-body"><div class="settings-policy"><strong>Pool Shed only</strong><p>Operational answers use authorised Pool Shed records and approved knowledge only. This policy cannot be disabled.</p></div><div class="settings-policy"><strong>Permission first</strong><p>Restricted modules, locations, margins, costs and financial fields are filtered before retrieval.</p></div></div></section><section class="settings-panel"><header><h2>Automation Authority</h2></header><div class="settings-panel-body"><p>Flow creation, activation and sensitive actions inherit role permissions and approval limits.</p>'+button('Open Automation Command','open-automation')+'</div></section></div>');return layout('Automation & Assistant','Assistant and automation configuration.','<div class="settings-empty">Automation workspace is unavailable.</div>');}
function integrationsPage(){const list=(d().integrations||[]).map(i=>String(i.name||'').toLowerCase()==='xero'&&/not connected/i.test(String(i.status||''))?{...i,status:'Ready to Connect'}:i);const extra=[{name:'Outlook Email',purpose:'Authorised customer and supplier communication',status:'Not connected'},{name:'Microsoft Teams',purpose:'Internal alerts and approval notifications',status:'Not connected'},{name:'API / Webhooks',purpose:'Signed integrations and automation actions',status:'Not configured'}];const by=new Set(list.map(i=>String(i.name).toLowerCase()));const all=list.concat(extra.filter(x=>!by.has(x.name.toLowerCase())));return layout('Integrations','Connection health, scopes and mappings. Secrets are never shown back in clear text.','<section class="settings-panel"><div class="settings-panel-body">'+all.map(i=>'<article class="settings-integration"><span class="integration-logo">'+esc((i.name||'?')[0])+'</span><div><strong>'+esc(i.name)+'</strong><small>'+esc(i.purpose||'Integration')+'</small></div>'+pill(i.status||'Not connected',/connected|healthy/i.test(String(i.status))?'good':'warn')+button('Manage','manage-integration','mini','data-integration="'+esc(i.name)+'"')+'</article>').join('')+'</div></section>',button('Connection Audit','integration-audit'));}
function notificationsPage(){const rules=sec.state().notificationRules.length?sec.state().notificationRules:[{event:'Customer credit warning',app:true,email:true,teams:false,recipients:'Accounts, Sales',escalation:'Management at 100%'},{event:'Supplier PO late',app:true,email:true,teams:true,recipients:'Purchasing',escalation:'3 days late'},{event:'Project margin warning',app:true,email:true,teams:true,recipients:'Management',escalation:'Below threshold'},{event:'Automation failure',app:true,email:true,teams:true,recipients:'Admin',escalation:'Immediate'}];sec.state().notificationRules=rules;return layout('Notifications','Choose how operational alerts, escalations and automation failures reach the right people.','<section class="settings-panel"><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>Event</th><th>In App</th><th>Email</th><th>Teams</th><th>Recipients</th><th>Escalation</th></tr></thead><tbody>'+rules.map((r,i)=>'<tr><td><strong>'+esc(r.event)+'</strong></td>'+['app','email','teams'].map(k=>'<td><button type="button" class="permission-toggle '+(r[k]?'on':'')+'" data-settings-action="toggle-notification" data-notification-index="'+i+'" data-channel="'+k+'">'+(r[k]?'✓':'–')+'</button></td>').join('')+'<td>'+esc(r.recipients)+'</td><td>'+esc(r.escalation)+'</td></tr>').join('')+'</tbody></table></div></section>',button('Save Rules','save-notifications','primary'));}
function companyPage(){const c=d().companySettings||{};return layout('Company Settings','Company identity and operational defaults used throughout Pool Shed.','<section class="settings-panel"><header><h2>Company Details</h2></header><div class="settings-panel-body"><div class="settings-form-grid"><label>Company name<input id="settingsCompanyName" value="'+esc(c.name||'Pool Bros')+'"></label><label>VAT / Company ref<input id="settingsCompanyVat" value="'+esc(c.vat||'')+'"></label><label>Phone<input id="settingsCompanyPhone" value="'+esc(c.phone||'')+'"></label><label>Email<input id="settingsCompanyEmail" value="'+esc(c.email||'')+'"></label><label class="wide">Address<textarea id="settingsCompanyAddress">'+esc(c.address||'')+'</textarea></label><label>Currency<select id="settingsCurrency"><option>GBP</option><option>EUR</option></select></label><label>Default payment terms<select id="settingsTerms"><option>30 days</option><option>14 days</option><option>7 days</option><option>Due on receipt</option></select></label></div></div></section><div class="settings-grid two"><section class="settings-panel"><header><h2>Numbering & Defaults</h2></header><div class="settings-panel-body"><p>Sales Orders, POs, Goods Notes, Projects, returns and finance references continue using the current system sequences.</p></div></section><section class="settings-panel"><header><h2>Commercial Thresholds</h2></header><div class="settings-panel-body"><p>Margin, credit and stock thresholds remain governed by their operational modules and can be surfaced here in the final production settings.</p></div></section></div>',button('Save Company Settings','save-company','primary'));}
function auditPage(){const canonical=global.PoolShedAudit&&typeof global.PoolShedAudit.query==='function'?global.PoolShedAudit.query({}).slice(0,100):[],legacy=(d().auditLog||[]).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,50);const rows=canonical.map(a=>({date:a.occurredAt,user:a.actor&&a.actor.name,action:a.action,target:a.record&&(a.record.label||a.record.id),reason:a.reason,category:a.category,severity:a.severity,canonical:true}));return layout('Audit & Security','Review sensitive changes, approvals, overrides, exports and integration/security events.','<div class="settings-toolbar"><input id="settingsAuditSearch" placeholder="Search audit activity"><span class="grow"></span>'+button('Export Audit','export-audit')+'</div><section class="settings-panel"><header><div><h2>Canonical audit events</h2><p>Append-only v1.26 authority. Normal staff UI cannot edit or delete these events.</p></div>'+pill(rows.length+' events','good')+'</header><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>Date</th><th>Actor</th><th>Action</th><th>Target</th><th>Reason</th><th>Category</th></tr></thead><tbody id="settingsAuditRows">'+(rows.length?rows.map(a=>'<tr><td>'+esc((a.date||'').replace('T',' ').slice(0,16))+'</td><td>'+esc(a.user||'')+'</td><td><strong>'+esc(a.action||'')+'</strong></td><td>'+esc(a.target||'')+'</td><td>'+esc(a.reason||'')+'</td><td>'+pill(a.category||'Audit',a.severity==='critical'?'danger':a.category==='Security'?'warn':'')+'</td></tr>').join(''):'<tr><td colspan="6"><div class="settings-empty">Canonical audit history begins with v1.26 actions.</div></td></tr>')+'</tbody></table></div></section><section class="settings-panel"><header><div><h2>Historical legacy audit</h2><p>Read-only history retained for context. These rows are not rewritten as canonical events.</p></div>'+pill(legacy.length+' shown','')+'</header><div class="settings-panel-body settings-table-wrap"><table class="settings-table"><thead><tr><th>Date</th><th>Actor</th><th>Action</th><th>Target</th><th>Reason</th><th>Category</th></tr></thead><tbody>'+legacy.map(a=>'<tr><td>'+esc((a.date||'').replace('T',' ').slice(0,16))+'</td><td>'+esc(a.user||'')+'</td><td><strong>'+esc(a.action||'')+'</strong></td><td>'+esc(a.target||a.product||'')+'</td><td>'+esc(a.reason||'')+'</td><td>'+pill(a.category||'Legacy','')+'</td></tr>').join('')+'</tbody></table></div></section>',button('Security Review','security-review','primary'));}
function renderSettingsCommand(){const target=document.getElementById('screen-settings');if(!target)return;const p=page();const fn={'Overview':overview,'Production Readiness':readinessPage,'Users':usersPage,'Roles & Permissions':rolesPage,'Approval Limits':approvalsPage,'Locations & Access':locationsPage,'Financial Visibility':financePage,'Automation & Assistant':assistantPage,'Integrations':integrationsPage,'Notifications':notificationsPage,'Company Settings':companyPage,'Audit & Security':auditPage}[p]||overview;target.innerHTML=fn();}
function modal(title,body,footer){document.getElementById('settingsCommandModal')?.remove();const el=document.createElement('div');el.id='settingsCommandModal';el.className='settings-modal-backdrop';el.innerHTML='<div class="settings-modal"><header><h2>'+esc(title)+'</h2><button type="button" data-settings-action="close-modal">×</button></header><div class="settings-modal-body">'+body+'</div><footer>'+footer+'</footer></div>';document.body.appendChild(el);}
function userEditor(id){const list=users(),u=list.find(x=>String(x.id)===String(id))||list[0];if(!u)return;const roles=sec.roles();const e=sec.effective(u);modal(u.name||'User','<div class="settings-form-grid"><label>Name<input id="editUserName" value="'+esc(u.name||'')+'"></label><label>Role<select id="editUserRole">'+roles.map(r=>'<option '+(r.id===e.role?'selected':'')+'>'+r.id+'</option>').join('')+'</select></label><label>Status<select id="editUserStatus"><option '+(u.status==='Active'?'selected':'')+'>Active</option><option '+(/disabled|suspend/i.test(String(u.status))?'selected':'')+'>Disabled</option></select></label><label>Email<input value="'+esc(u.email||'')+'" disabled></label></div><div class="settings-callout info"><strong>Individual overrides</strong><p>Use deliberate grants/denies only when this user must differ from the base role. Deny always wins.</p></div>',button('View as '+(u.name||'User').split(' ')[0],'preview-specific','','data-user-id="'+esc(u.id)+'"')+button('Save User','save-user','primary','data-user-id="'+esc(u.id)+'"'));}
function previewUser(id){const list=users(),u=list.find(x=>String(x.id)===String(id))||list.find(x=>x.role==='Engineer')||list[0];if(!u)return;const p=sec.preview(u);modal('View system as '+u.name,'<div class="settings-callout good"><strong>Preview mode only</strong><p>No authentication or business record is changed. This calculates the access Pool Shed would enforce for '+esc(u.name)+'.</p></div><div class="settings-preview"><div><h3>Visible navigation</h3><div class="preview-tags">'+sec.modules().map(m=>pill(MODULE_LABELS[m]||m,p.visibleModules.includes(m)?'good':'muted')).join('')+'</div></div><div><h3>Financial visibility</h3><div class="preview-tags">'+FIN.map(([key,label])=>pill(label,p.hiddenFinancial.includes(key)?'danger':'good')).join('')+'</div></div><div><h3>Assistant</h3><p>Assistant can retrieve from: '+esc(p.assistantModules.map(m=>MODULE_LABELS[m]||m).join(', ')||'No operational modules')+'.</p><p>Full System Export: <strong>'+(p.fullSystemExport?'Allowed':'Blocked')+'</strong></p></div></div>',button('Close','close-modal','primary'));}
function addUser(){modal('Add User','<div class="settings-callout info"><strong>Authentication remains in Supabase</strong><p>Create/invite the authentication account first, then link its User UID to the Pool Shed profile.</p></div><div class="settings-form-grid"><label>Supabase User UID<input id="newUserId"></label><label>Full name<input id="newUserName"></label><label>Email<input id="newUserEmail" type="email"></label><label>Base role<select id="newUserRole">'+sec.roles().map(r=>'<option>'+r.id+'</option>').join('')+'</select></label></div>',button('Cancel','close-modal')+button('Add User','confirm-add-user','primary'));}
function exportAudit(){if(global.PoolShedAudit&&typeof global.PoolShedAudit.export==='function'){const payload=global.PoolShedAudit.export({});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='pool-shed-canonical-audit-v1.41.0.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);return;}const rows=(d().auditLog||[]),cols=['date','user','action','target','reason','category'],q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"',csv=[cols.join(',')].concat(rows.map(r=>cols.map(c=>q(r[c]??(c==='target'?r.product:''))).join(','))).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='pool-shed-security-audit.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);sec.audit('Security audit exported','Audit & Security','',rows.length+' rows','Authorised audit export');}
function handle(action,el){if(action==='goto-page'){activeSubPage.settings=el.dataset.pageTarget;return renderNow();}if(action==='preview-user')return previewUser();if(action==='preview-specific')return previewUser(el.dataset.userId);if(action==='add-user')return addUser();if(action==='edit-user')return userEditor(el.dataset.userId);if(action==='close-modal')return document.getElementById('settingsCommandModal')?.remove();if(action==='confirm-add-user'){const list=users(),id=document.getElementById('newUserId').value.trim(),name=document.getElementById('newUserName').value.trim(),email=document.getElementById('newUserEmail').value.trim(),role=document.getElementById('newUserRole').value;if(!id||!name||!email)return toastMsg('User UID, name and email are required.');list.push({id,name,email,role,status:'Active'});global.__POOL_SHED_SAVE_USERS__?.(list);sec.audit('User profile created',id,'',role,'New staff access profile');document.getElementById('settingsCommandModal')?.remove();toastMsg('User profile added.');return renderNow();}if(action==='save-user'){const list=users(),u=list.find(x=>String(x.id)===String(el.dataset.userId));if(u){const before={name:u.name,role:u.role,status:u.status};u.name=document.getElementById('editUserName').value.trim();u.role=document.getElementById('editUserRole').value;u.status=document.getElementById('editUserStatus').value;global.__POOL_SHED_SAVE_USERS__?.(list);sec.audit('User profile changed',u.id,before,{name:u.name,role:u.role,status:u.status},'Admin user update');}document.getElementById('settingsCommandModal')?.remove();toastMsg('User access updated.');return renderNow();}if(action==='toggle-role-permission'){const now=sec.roleMatrix(selectedRole)[el.dataset.module][el.dataset.operation];const res=sec.setRolePermission(selectedRole,el.dataset.module,el.dataset.operation,!now,'Role Builder change');if(res&&res.ok===false)return toastMsg(res.reason);return renderNow();}if(action==='save-role'){toastMsg(selectedRole+' role saved and audited.');return;}if(action==='save-approval'){document.querySelectorAll('[data-approval-role][data-approval-key]').forEach(i=>{if(i.disabled)return;const v=String(i.value).trim();sec.setApprovalLimit(i.dataset.approvalRole,i.dataset.approvalKey,/unlimited/i.test(v)?null:Number(String(v).replace(/[^0-9.]/g,''))||0,'Approval Limits save');});toastMsg('Approval limits saved.');return renderNow();}if(action==='test-approval'){const r=sec.approvalRoute('purchaseOrder',12000,{id:'preview-purchasing',role:'Purchasing'});return modal('Approval Route Test','<div class="settings-callout '+(r.allowed?'good':'warn')+'"><strong>£12,000 Purchase Order</strong><p>'+esc(r.reason)+(r.escalateTo?' · routes to '+r.escalateTo:'')+'. Purchasing limit: £'+Number(r.limit||0).toLocaleString('en-GB')+'.</p></div>',button('Close','close-modal','primary'));}if(action==='toggle-location'){const u=users().find(x=>String(x.id)===String(el.dataset.userId));if(!u)return;let scope=sec.effective(u).locations.slice();const id=el.dataset.locationId;if(!scope.length){scope=(d().locations||[]).map(l=>String(l.id));}scope=scope.includes(id)?scope.filter(x=>x!==id):scope.concat(id);sec.setLocationScope(u.id,scope,'Location access matrix');return renderNow();}if(action==='save-location-scope'){toastMsg('Location access is already saved and audited as changes are made.');return;}if(action==='toggle-finance'){const current=sec.financeMatrix(el.dataset.role)[el.dataset.financeKey];sec.setFinancialVisibility(el.dataset.role,el.dataset.financeKey,!current,'Financial Visibility matrix');return renderNow();}if(action==='save-financial-visibility'){toastMsg('Financial visibility saved and audited.');return;}if(action==='toggle-notification'){const r=sec.state().notificationRules[Number(el.dataset.notificationIndex)];if(r)r[el.dataset.channel]=!r[el.dataset.channel];save();return renderNow();}if(action==='save-notifications'){sec.audit('Notification rules updated','Notifications','','Saved','Notification governance');toastMsg('Notification rules saved.');return;}if(action==='save-company'){const c=d().companySettings=d().companySettings||{},before={name:c.name,vat:c.vat};c.name=document.getElementById('settingsCompanyName').value.trim();c.vat=document.getElementById('settingsCompanyVat').value.trim();c.phone=document.getElementById('settingsCompanyPhone').value.trim();c.email=document.getElementById('settingsCompanyEmail').value.trim();c.address=document.getElementById('settingsCompanyAddress').value.trim();save();sec.audit('Company settings changed','Company Settings',before,{name:c.name,vat:c.vat},'Company configuration update');toastMsg('Company settings saved.');return;}if(action==='manage-integration'){if(String(el.dataset.integration||'').toLowerCase()==='xero')return modal('Xero Connection Readiness','<div class="settings-callout good"><strong>Ready to Connect</strong><p>Pool Shed has the Xero OAuth, encrypted token, webhook, tenant and reconciliation architecture prepared.</p></div><div class="settings-callout warn" style="margin-top:10px"><strong>Live connection locked</strong><p>No Xero organisation will be authorised, imported or synchronised until production acceptance is complete and XERO_INTEGRATION_MODE is deliberately changed to live.</p></div><div class="settings-callout info" style="margin-top:10px"><strong>Prepared data boundary</strong><p>Invoices and credit notes can be managed with accounting.invoices; contacts and settings are read-only; payments are read-only for reconciliation. Credentials remain server-side and masked.</p></div>',button('Close','close-modal')+button('Record Readiness Review','record-integration-review','primary','data-integration="Xero"'));return modal(el.dataset.integration+' Connection','<div class="settings-callout info"><strong>Credentials remain masked</strong><p>Manage connection health, scopes and field mappings here. Existing secrets are never rendered back in clear text.</p></div>',button('Close','close-modal')+button('Record Review','record-integration-review','primary','data-integration="'+esc(el.dataset.integration)+'"'));}if(action==='record-integration-review'){sec.audit('Integration reviewed',el.dataset.integration,'','Reviewed','Integration security review');document.getElementById('settingsCommandModal')?.remove();return toastMsg('Integration review recorded.');}if(action==='integration-audit'){sec.audit('Integration connection audit','Integrations','','Audit run','Connection health check');return toastMsg('Connection audit recorded.');}if(action==='open-automation'){active='automation';return renderNow();}if(action==='run-readiness-check'){toastMsg('Production readiness check refreshed from current Pool Shed data.');return renderNow();}if(action==='open-readiness-issue'){const e=global.PoolShedProductionReadiness;if(!e)return;const r=e.inspect(),found=r.issues.find(x=>x.code===el.dataset.readinessCode);if(!found)return toastMsg('Readiness item is no longer present.');const rt=e.routeForIssue(found);if(rt.module==='settings'){active='settings';activeSubPage.settings=rt.page||'Production Readiness';}else{active=rt.module;if(rt.page){activeSubPage[rt.module]=rt.page;}}toastMsg('Opened '+(rt.page||rt.module)+' for '+found.title+'.');return renderNow();}if(action==='export-readiness-report'){const e=global.PoolShedProductionReadiness;if(!e)return;const r=e.inspect(),blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pool-shed-production-readiness-v'+r.version+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);sec.audit('Production readiness report exported','Production Readiness','',r.status,'Read-only release diagnostic export');return toastMsg('Production readiness report downloaded.');}if(action==='export-audit')return exportAudit();if(action==='open-audit'){activeSubPage.settings='Audit & Security';return renderNow();}if(action==='security-review'){sec.audit('Security review completed','Settings','','Review started','Manual security review');return toastMsg('Security review recorded.');}}
function renderNow(){try{if(typeof global.render==='function')global.render();else renderSettingsCommand();}catch(_){renderSettingsCommand();}}
const previousRender=typeof global.renderSettings==='function'?global.renderSettings:null;global.renderSettings=function(){renderSettingsCommand();};
const previousGroups=typeof global.sidebarSubGroups==='function'?global.sidebarSubGroups:null;if(previousGroups){global.sidebarSubGroups=function(id){if(id==='settings')return PAGES.slice();return previousGroups(id);};}
document.addEventListener('click',e=>{const p=e.target.closest&&e.target.closest('[data-settings-page]');if(p){e.preventDefault();active='settings';activeSubPage.settings=p.dataset.settingsPage;return renderNow();}const r=e.target.closest&&e.target.closest('[data-settings-role]');if(r){e.preventDefault();selectedRole=r.dataset.settingsRole;activeSubPage.settings='Roles & Permissions';return renderNow();}const a=e.target.closest&&e.target.closest('[data-settings-action]');if(a){e.preventDefault();return handle(a.dataset.settingsAction,a);}});
document.addEventListener('change',e=>{if(e.target&&e.target.matches('[data-permission-inspector-user]')){inspectorUserId=e.target.value;return renderNow();}if(e.target&&e.target.matches('[data-permission-inspector-module]')){inspectorModule=e.target.value;return renderNow();}if(e.target&&e.target.matches('[data-permission-inspector-operation]')){inspectorOperation=e.target.value;return renderNow();}});
document.addEventListener('input',e=>{if(e.target&&e.target.id==='settingsUserSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#settingsUserRows tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q));}if(e.target&&e.target.id==='settingsAuditSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#settingsAuditRows tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q));}});
global.PoolShedSettingsCommand={pages:PAGES.slice(),render:renderSettingsCommand,setPage:p=>{active='settings';activeSubPage.settings=p;renderNow();},previewUser};
})(typeof globalThis!=='undefined'?globalThis:window);
